import React, { useEffect, useState, useRef } from "react";
import Banner from "./Banner";
import axios from "axios";
import "../styles/main.css";

export default function Academics() {
  const [data, setData] = useState({});
  const sectionRefs = useRef({});

  useEffect(() => {
    axios.get("http://localhost:5000/api/academics")
      .then(res => setData(res.data || {}))
      .catch(err => console.error(err));
  }, []);

  const scrollToSection = (sectionKey) => {
    const ref = sectionRefs.current[sectionKey];
    if (ref) {
      ref.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  return (
    <>
      <Banner />
      <main className="main-container">
        <div className="two-column">
          {/* Left menu */}
          <div className="left-column">
            <h2>Academics</h2>
            <div className="points-box">
              {Object.keys(data).map((key) => (
                <p key={key} onClick={() => scrollToSection(key)} style={{ cursor: "pointer" }}>
                  {key.charAt(0).toUpperCase() + key.slice(1)}
                </p>
              ))}
            </div>
          </div>

          {/* Right content */}
          <div className="right-column">
            {Object.entries(data).map(([key, html]) => (
              <div key={key} ref={(el) => (sectionRefs.current[key] = el)}>
                <h2>{key.charAt(0).toUpperCase() + key.slice(1)}</h2>
                <div dangerouslySetInnerHTML={{ __html: html }} />
              </div>
            ))}
          </div>
        </div>
      </main>
    </>
  );
}
